                $formDefinition = [
                    'type' => 'Form',
                    'identifier' => $persistenceIdentifier,
                    'label' => $e->getMessage(),
                    'invalid' => true,
                ];
            }
            $this->runtimeCache->set($cacheKey, $formDefinition);
        }

